(async () => {
  const results = {};

  // 1. 先点击退出（如果已登录）
  const logoutBtn = document.querySelector('#logoutBtn');
  if (logoutBtn && logoutBtn.offsetParent !== null) {
    logoutBtn.click();
    await new Promise(r => setTimeout(r, 300));
  }

  // 2. 测试无效邮箱 invalid-email
  const emailInput = document.querySelector('#email');
  const passwordInput = document.querySelector('#password');
  const loginBtn = document.querySelector('#loginBtn');

  emailInput.value = 'invalid-email';
  passwordInput.value = 'password123';
  emailInput.dispatchEvent(new Event('input', { bubbles: true }));
  passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

  loginBtn.click();
  await new Promise(r => setTimeout(r, 500));

  // 读取无效邮箱的validity
  results.invalidEmail = {
    value: emailInput.value,
    typeMismatch: emailInput.validity.typeMismatch,
    validationMessage: emailInput.validationMessage,
    valid: emailInput.validity.valid
  };

  // 读取错误节点可见性
  const customError = document.querySelector('#emailError');
  results.customErrorVisible = customError ? (getComputedStyle(customError).display !== 'none') : false;

  // 读取表单和用户区可见性
  const loginForm = document.querySelector('#loginForm');
  const userInfo = document.querySelector('#userInfo');
  results.loginFormVisible = loginForm ? (getComputedStyle(loginForm).display !== 'none') : false;
  results.userInfoVisible = userInfo ? (getComputedStyle(userInfo).display !== 'none') : false;

  // 3. 测试错误密码
  emailInput.value = 'test@example.com';
  passwordInput.value = 'wrongpassword';
  emailInput.dispatchEvent(new Event('input', { bubbles: true }));
  passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

  // 拦截alert
  let capturedAlert = null;
  const originalAlert = window.alert;
  window.alert = (msg) => {
    capturedAlert = msg;
    // 不阻止原alert执行
  };

  loginBtn.click();
  await new Promise(r => setTimeout(r, 800));

  // 恢复原alert
  window.alert = originalAlert;

  results.wrongPassword = {
    emailValue: emailInput.value,
    passwordValue: passwordInput.value,
    capturedAlert: capturedAlert,
    loginFormVisible: getComputedStyle(loginForm).display !== 'none',
    userInfoVisible: getComputedStyle(userInfo).display !== 'none'
  };

  // 4. 测试正确登录
  emailInput.value = 'test@example.com';
  passwordInput.value = 'password123';
  emailInput.dispatchEvent(new Event('input', { bubbles: true }));
  passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

  loginBtn.click();
  await new Promise(r => setTimeout(r, 500));

  // 读取登录后状态
  const userInfoRect = userInfo.getBoundingClientRect();
  results.correctLogin = {
    userInfoVisible: getComputedStyle(userInfo).display !== 'none',
    loginFormVisible: getComputedStyle(loginForm).display !== 'none',
    userInfoRect: {
      x: userInfoRect.x,
      y: userInfoRect.y,
      width: userInfoRect.width,
      height: userInfoRect.height,
      right: userInfoRect.right,
      bottom: userInfoRect.bottom
    },
    innerWidth: window.innerWidth,
    scrollWidth: document.documentElement.scrollWidth,
    localStorage: localStorage.getItem('macbot-e2e-s2-parallel-fc45ecd3b62c')
  };

  return results;
})()

